40	const MARKER_VISIBILITY_LABELS: Record<MarkerVisibility, string> = {
41	  all: 'All eligible kinds (status quo)',
42	  'with-children': 'Only nodes that have children',
43	  'headings-and-paragraphs': 'Only headings and paragraphs',
44	};
45	
46	const GUIDE_HIGHLIGHT_LABELS: Record<GuideHighlight, string> = {
47	  off: 'No highlight',
48	  full: 'Whole guide of every ancestor',
49	  lineage: 'Only the part leading down to the cursor',
50	};
51	
52	const MARKER_HIGHLIGHT_LABELS: Record<MarkerHighlight, string> = {
53	  off: 'No highlight',
54	  current: 'The current node only',
55	  lineage: 'The current node and all its ancestors',
56	};
57	
58	/**
59	 * Note: `indent`/`outdent` also accept an optional trailing
60	 * `fallbackIndentUnit` (the unit to use for brand-new indentation with no
61	 * existing evidence in the document — see ops.ts's `destinationIndent`).
62	 * The command-palette path here can't supply it: Obsidian's public `Editor`/
63	 * `MarkdownView` API doesn't expose the underlying CM6 `EditorState`, so
64	 * there's no public-API way to read the live "Indent using tabs" setting
65	 * (the `@codemirror/language` `indentUnit` facet) from a command callback
66	 * the way keymap.ts's Tab/Shift-Tab handler and transaction-filter.ts's
67	 * paste path do. These commands fall back to inferring from the document's
68	 * own existing indentation, same as before this fix — a known, small gap
69	 * limited to the command-palette / custom-hotkey entry point.
70	 */
71	type StructuralOp = (doc: OutlineDoc, nodeId: number) => OpResult<OpOutput>;
72	
73	/**
74	 * The cursor a palette-invoked structural command should end on: decided by
75	 * `caret-policy.ts`, the same procedure `grammar.ts` uses for the keyboard
76	 * path, so the two entry points cannot diverge.
77	 *
78	 * This function is now purely an adapter — it converts Obsidian's `{line,
79	 * ch}` world into the policy's facts and back. It holds no rule of its own;
80	 * the previous version re-implemented the mapped-with-addressability-fallback
81	 * rule here, and had already drifted once (the palette missed the
82	 * addressability guard entirely until review caught it).
83	 */
84	function resultCursor(
85	  lines: readonly string[],
86	  newLines: readonly string[],
87	  changes: readonly EditorChange[],
88	  before: OutlineDoc,
89	  op: CaretOp,
90	  anchor: { line: number; ch: number },
91	  mapFrom?: { line: number; ch: number },
92	): { line: number; ch: number } {
93	  const after = parse(newLines.join('\n'));
94	  const mapped =
95	    mapFrom === undefined
96	      ? undefined
97	      : offsetToPos(newLines, mapCursorForward(lines, changes, mapFrom));
98	  return planCaret(op, { before, after, anchor, mapped }).caret;
99	}
100	
101	/** Flat character offset (as `mapCursorForward` returns) → `{line, ch}`, for
102	 * Obsidian's public `Editor.setCursor`. */
103	function offsetToPos(lines: readonly string[], offset: number): { line: number; ch: number } {
104	  let acc = 0;
105	  for (let line = 0; line < lines.length; line++) {
106	    const len = lines[line]?.length ?? 0;
107	    if (offset <= acc + len) return { line, ch: offset - acc };
108	    acc += len + 1;
109	  }
110	  return { line: Math.max(0, lines.length - 1), ch: lines[lines.length - 1]?.length ?? 0 };
111	}
112	
113	const CONFLICTING_PLUGINS = ['obsidian-outliner', 'obsidian-zoom'];
114	
115	export default class TrueOutlinerPlugin extends Plugin {
116	  private data: PluginData = { ...DEFAULT_DATA };
117	  private registry!: OutlineModeRegistry;
118	  /** Public so the e2e harness can read classification evidence the same
119	   * way it already reads `isOutline` (design.md D8). */
120	  readonly stats = new TransactionStats();
121	
122	  /**
123	   * Per-key keymap-liveness counters, same "public for the harness" rationale
124	   * as `stats`. Populated only in dev builds (see `showDevBuildStamp`).
125	   *
126	   * These exist so e2e can assert the MECHANISM and not only the outcome. A
127	   * caret can land in the right place without our keymap ever running — the
128	   * transaction filter corrects native motion after the fact — so an
129	   * outcome-only test passes identically whether our handler fired or never
130	   * existed. That blind spot hid a real defect through three rewrites of the
131	   * Home/End logic (docs/research/04 Q27).
132	   */
133	  readonly motionCounts: Record<string, { invoked: number; consumed: number }> = {};
134	
135	  /** The stamp compiled into THIS bundle. Public so the dev hot-reload plugin
136	   * can name the build it just loaded: `manifest.json` is copied verbatim and
137	   * cached by Obsidian anyway, so it only ever reports the base package
138	   * version. */
139	  readonly buildStamp = BUILD_STAMP;
140	
