107	/**
108	 * The forest cover spanning `startNode`..`endNode`, as DELETION GROUPS —
109	 * one contiguous sibling run per parent, in document order, `groups[0]`
110	 * topmost. That is exactly `deleteSubtreeGroups`' input shape
111	 * (`fix-orphan-gap-on-node-deletion` D2), so a mixed-depth cover needs no
112	 * deletion machinery of its own.
113	 *
114	 * The roots come from `escalate.ts`'s exported `forestCoverOf` rather than a
115	 * second scope resolution here — one implementation, every consumer
116	 * (`selection-as-subtree-set` D4). The grouping is the only thing this adds:
117	 * a forest span is an interval in document order, so it cannot straddle a
118	 * parent's children non-contiguously, and consecutive roots sharing a parent
119	 * are therefore always a contiguous run.
120	 */
121	function coverGroups(
122	  doc: OutlineDoc,
123	  startNode: OutlineNode,
124	  endNode: OutlineNode,
125	): readonly (readonly number[])[] {
126	  return groupRootsByParent(forestCoverOf(doc, startNode, endNode).roots);
127	}
128	
129	/**
130	 * Roots (document order) split into one contiguous sibling run per parent.
131	 * A forest span is an interval in document order, so it cannot straddle a
132	 * parent's children non-contiguously — consecutive roots sharing a parent
133	 * are therefore always a contiguous run, and a parent change always starts a
134	 * new group.
135	 *
136	 * Every caller that hands roots to `deleteSubtreeGroups` MUST go through
137	 * this: that function resolves each group with `resolveContiguousGroup`,
138	 * which REJECTS a group whose members do not share a parent — and a
139	 * rejection here is a veto, i.e. the user's whole deletion silently refused.
140	 * Reads `ForestRoot.path` rather than calling `findPath` per root, which was
141	 * a full-tree search per root (Θ(n²) for a forest of n roots).
142	 */
143	export function groupRootsByParent(roots: readonly ForestRoot[]): readonly (readonly number[])[] {
144	  const groups: number[][] = [];
145	  let currentParent: string | undefined;
146	  for (const root of roots) {
147	    const parentKey = root.path.slice(0, -1).join('/');
148	    if (parentKey !== currentParent) {
149	      groups.push([]);
150	      currentParent = parentKey;
151	    }
152	    groups[groups.length - 1]!.push(root.node.id);
153	  }
154	  return groups;
155	}
156	
157	/** The deletion's OLD-document range removes NOTHING but the single line
158	 * break ending `from.line` — i.e. `from` sits at that line's own end and
159	 * `to` at the very start of the next. Distinct from "ends at a line start"
160	 * in general: a whole-line-or-more deletion (e.g. removing an entire node)
161	 * can ALSO end at ch 0 of a later line without this being true. */
162	function isPureNewlineDeletion(doc: OutlineDoc, edit: EditFact): boolean {
163	  if (edit.insert !== '') return false;
164	  if (edit.to.line !== edit.from.line + 1 || edit.to.ch !== 0) return false;
165	  const lineLen = (encodeLines(doc)[edit.from.line] ?? '').length;
166	  return edit.from.ch === lineLen;
167	}
168	
169	function posEq(a: LinePos | undefined, b: LinePos): boolean {
170	  return a !== undefined && a.line === b.line && a.ch === b.ch;
171	}
